  static final Map<int, CanMessageDefinition> _messagesById =
      <int, CanMessageDefinition>{
        0x110: pedalStatus,
        0x210: auxCommand,
        0x310: packPower,
        0x311: auxPower,
        0x312: packEnergy,
        0x400: vehicleMotion,
