        0x604: motorEstimator,
        0x605: motorPhaseCurrent,
      };

  static CanMessageDefinition? messageById(int canId) => _messagesById[canId];

  static DecodedCanMessage? decode(int canId, Uint8List data) {
    switch (canId) {
      case 0x110:
        return _decodePedalStatus(data);
      case 0x210:
        return _decodeAuxCommand(data);
      case 0x310:
        return _decodePackPower(data);
      case 0x311:
        return _decodeAuxPower(data);
      case 0x312:
        return _decodePackEnergy(data);
      case 0x400:
        return _decodeVehicleMotion(data);
      case 0x401:
        return _decodeVehicleTime(data);
      case 0x410:
        return _decodeGpsStatus(data);
      case 0x411:
        return _decodeGpsPosition(data);
      case 0x412:
        return _decodeGpsMotion(data);
      case 0x600:
        return _decodeMotorState(data);
      case 0x601:
        return _decodeMotorCurrent(data);
      case 0x602:
        return _decodeMotorVoltage(data);
      case 0x603:
        return _decodeMotorFaults(data);
      case 0x604:
        return _decodeMotorEstimator(data);
      case 0x605:
        return _decodeMotorPhaseCurrent(data);
      default:
        return null;
    }
  }

  static DecodedCanMessage _decodePedalStatus(Uint8List data) {
    _requireLength(data, pedalStatus);
    return DecodedCanMessage(
      definition: pedalStatus,
      signals: <String, double>{
        "throttle_command": _decodeSignal(data, pedalStatus.signals[0]),
        "throttle_inhibit": _decodeSignal(data, pedalStatus.signals[1]),
        "deadman_active": _decodeSignal(data, pedalStatus.signals[2]),
        "adc_fault": _decodeSignal(data, pedalStatus.signals[3]),
        "brake_active": _decodeSignal(data, pedalStatus.signals[4]),
        "is_calibrating": _decodeSignal(data, pedalStatus.signals[5]),
        "inhibit_reason": _decodeSignal(data, pedalStatus.signals[6]),
        "seq_counter": _decodeSignal(data, pedalStatus.signals[7]),
        "throttle_adc_raw": _decodeSignal(data, pedalStatus.signals[8]),
      },
    );
  }

